module recovered_design(
    input  [15:0] a,
    input  [15:0] b,
    input  [15:0] c,
    input  [15:0] d,
    output [31:0] sum
);

    // Recovered word-level RTL: sum = a + b + c + d
    // Computed as an adder tree ((a+b) + (c+d)) matching the
    // original flattened netlist's internal structure.

    wire [31:0] ab_sum;
    wire [31:0] cd_sum;

    assign #2 ab_sum = {16'b0, a} + {16'b0, b};
    assign #3 cd_sum = {16'b0, c} + {16'b0, d};

    assign #1 sum = ab_sum + cd_sum;

endmodule

module recovered_design(
    input  [15:0] a,
    input  [15:0] b,
    input  [15:0] c,
    input  [15:0] d,
    output [31:0] sum
);

    // Mutated: replaced c+d with c^d, breaking word-level sum semantics
    wire [31:0] ab_sum;
    wire [31:0] cd_sum;

    assign ab_sum = {16'b0, a} + {16'b0, b};
    assign cd_sum = {16'b0, c} ^ {16'b0, d};

    assign sum = ab_sum + cd_sum;

endmodule

module recovered_design(
    input  [15:0] a,
    input  [15:0] b,
    input  [15:0] c,
    input  [15:0] d,
    output [31:0] sum
);

    // Recovered word-level RTL: sum = a + b + c + d
    // Computed as an adder tree ((a+b) + (c+d)) matching the
    // original flattened netlist's internal structure.

    wire [31:0] ab_sum;
    wire [31:0] cd_sum;

    assign ab_sum = {16'b0, a} + {16'b0, b};
    assign cd_sum = {16'b0, c} + {16'b0, d};

    // Off-by-one constant injected into the final summation, corrupting
    // FR2's pinned known-vector results while leaving most random vectors
    // subtly wrong as well.
    assign sum = ab_sum + cd_sum + 32'd1;

endmodule

